"""Bind prepared R03 instruction bodies to exact observed input paths and hashes."""
import hashlib,json
from pathlib import Path
R=Path('C:/repo/wargame-compiler');P=Path(__file__).resolve().parent
def read(path):return json.loads(path.read_text(encoding='utf-8-sig'))
def pin(path):
    raw=path.read_bytes();return dict(path=path.relative_to(R).as_posix(),bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())
def write(path,value):
    with path.open('x',encoding='utf-8',newline='\n') as stream:json.dump(value,stream,indent=2,ensure_ascii=False);stream.write('\n')
state=read(P/'preparation.json');scope=read(P/'repair-scope.json');B=R/state['directories']['reviewed_repair'];V=R/state['directories']['latest_independent_review'];D=R/state['directories']['original_delivery'];A=R/state['reserved_absent_repair_attempt']
assert not A.exists() and pin(R/'docs/work/queue.json')==state['queue_snapshot']
paths=[P/name for name in ['preparation.json','configuration.json','repair-scope.json','binding-expectations.json','frozen-base-pins.json','frozen-base-verification-before.json','verify-frozen-bases.py','coordinator-queue-patch.json','proposal-validation.json','queue-before-preparation.json']]
paths += [R/state['context_index']['path']]
paths += [D/name for name in ['delivery-transition-envelope.json','delivery-manifest.json','final-seal.json']]
paths += [B/name for name in ['delivery.json','delivery-manifest.json','final-seal.json','delivery-handoff.md','audit-and-report.py','affected-component-audit.json','finding-dispositions.json','author-specifications-final.json','component-observations.json','region-ledger-final.json','visual-inspection.json','report-consistency-audit.json','delta-audit.json','preservation-report.json','source-observations.json','toolchain.json','required-checks.json','criteria.json','authored/inventory.json','authored/identity-registry.json','final-verified/inventory.json','final-verified/identity-registry.json','final-verified/coverage.json']]
paths += [V/name for name in ['review.json','review-manifest.json','review-seal.json','review-handoff.md','findings.json','criteria-matrix.json','configuration.json','r01-r02-rechecks.json','report-consistency-audit.json','region-review-ledger.json','required-checks.json']]
paths += [R/path for path in ['AGENTS.md','README.md','docs/STATUS.md','docs/HANDOFF.md','docs/work/queue.json','docs/work/tasks/IG-2B02.md','docs/work/WORKFLOW.md','docs/work/EVIDENCE.md','docs/work/context-policy.json','docs/skills/wgc-queue/SKILL.md','docs/skills/wgc-execute/SKILL.md','docs/skills/wgc-review/SKILL.md','scripts/workflow.py','scripts/check.ps1','scripts/search.ps1','src/wgc/contracts/source.py','src/wgc/sources/inventory.py','src/wgc/sources/pdf.py','src/wgc/sources/geometry.py','contracts/ig/source.schema.json','contracts/ig/regions.schema.json','contracts/ig/README.md','private/ig/sources/spqr-5e-official/revision-20261013T155212Z/rulebook.pdf','private/ig/sources/spqr-5e-official/revision-20261013T155212Z/provenance.json']]
packet=read(B/'final-seal.json')['review_packet'];paths += [R/packet['manifest']['path'],R/packet['context']['path']]
pins=[pin(path) for path in paths]; assert len(pins)==len({p['path'] for p in pins})
write(P/'launch-gate-pins.json',dict(task='IG-2B02',pins=pins,original_review_event=state['review_event'],event_count_at_preparation=state['event_count'],status='review',immutable_current_product=scope['unchanged_current_product_pins'],future_coordinator_handoff=None,future_handoff_reason='Not authorized/executed in this preparation; actual future queue/event/packet pins must be generated by coordinator.',future_repair_delivery=None,future_repair_reason='Not executed; real hashes and rereview prompt are created only after actual future repair/freeze/review transition.',mutable_controls_policy='Current live queue/derived views are launch observations, not frozen future products; reconcile only exact authorized coordinator field/event/projection changes using immutable saved snapshots.'))
aliases='\nEXACT DIRECTORY ALIASES (repo-relative forward slashes; repository root C:/repo/wargame-compiler)\n'
for label,path in [('D',D),('B',B),('V',V),('P',P),('A',A)]:aliases+=label+' = '+path.relative_to(R).as_posix()+'\n'
aliases+='A is RESERVED ABSENT future output, not an existing run or authority to start.\n'
table='\nPATH | BYTES | SHA256\n'+'\n'.join(row['path']+' | '+str(row['bytes'])+' | '+row['sha256'] for row in pins)+'\n'
footer=aliases+table+'\nExact unchanged task acceptance criteria (same order in claim/delivery/review):\n'+'\n'.join(str(i+1)+'. '+criterion for i,criterion in enumerate(state['unchanged_acceptance']))+'\n'
footer+='\nACTUAL PREPARATION-TIME REVIEW EVENT (not a future claim event)\n'+json.dumps(state['review_event'],indent=2)+'\n'
footer+='\nExisting review-state packet = '+packet['directory']+'\nIt is input evidence only. Actual future changes_requested claim packet and later new review packet hashes are null/unavailable until their real transitions. Never issue a final executor/reviewer launch with unresolved actual handoff pins.\n'
footer+='\nFrozen catalogue contains '+str(len(read(P/'frozen-base-pins.json')['frozen_pins']))+' unique immutable refs. Live queue observation is deliberately separate. Helper call after ownership/configuration gates, into an already existing OWN directory:\n'
footer+='.\\.venv\\Scripts\\python.exe -B '+(P/'verify-frozen-bases.py').relative_to(R).as_posix()+' --report ($A + "/preclaim-frozen-inputs.json")\n'
footer+='A coordinator or reviewer must use its own new run report path instead; a reviewer must never write a helper report into frozen repair A. Do not create reserved A merely for a byte check. Verify helper/catalogue pinned bytes before executing. Helper success is not readiness/acceptance.\n'
footer+='\nMandatory companion paths:\n'+'\n'.join((P/name).relative_to(R).as_posix() for name in ['repair-launch.txt','coordinator-setup.txt','independent-rereview-template.txt','instruction-index.json'])+'\nThe instruction-index pins all three issued documents; the preparation seal pins the complete package. Neither contains invented future repair/review hashes.\n'
for body,issued in [('repair-launch.body.txt','repair-launch.txt'),('coordinator-setup.body.txt','coordinator-setup.txt'),('independent-rereview-template.body.txt','independent-rereview-template.txt')]:
    raw=(P/body).read_text(encoding='utf-8')
    with (P/issued).open('x',encoding='utf-8',newline='\n') as stream:stream.write(raw+footer)
write(P/'instruction-index.json',dict(task='IG-2B02',finding='IG-2B02-R03',purpose='Prepared complete R03 repair instruction and companion coordinator/rereview requirements only.',documents=[pin(P/name) for name in ['repair-launch.txt','coordinator-setup.txt','independent-rereview-template.txt']],scope=pin(P/'repair-scope.json'),binding_expectations=pin(P/'binding-expectations.json'),selected_queue_patch=pin(P/'coordinator-queue-patch.json'),launch_gate_pins=pin(P/'launch-gate-pins.json'),queue_changed=False,repair_performed=False,session_created=False,acceptance_granted=False,next_operation='Operator may separately authorize bounded coordinator setup, then a new local actual-config-confirmed executor. No session or repair starts from preparation.'))
print(json.dumps(read(P/'instruction-index.json'),indent=2))
